const state={token:'',user:null,stats:null,rooms:[],room:null,page:'loading',busy:false,stream:null,connected:false,connection:'连接中',raise:0,modal:null,createKeyRequired:false,activityOpen:false,commitmentMismatch:false,reconnectTimer:null,install:null,replayTimer:null,timeOffset:0,revealed:new Set(),error:'',authMode:'login',pendingRecovery:null,chatOpen:false,chatDraft:'',chatBusy:false,chatPending:null,chatUnread:0,chatMuted:false,reactionsMuted:false,animations:true,reactions:{},motion:null,composing:false,renderDeferred:false,library:{hands:[],nextCursor:null,favorites:false,room:'',loading:false,error:'',request:0},replaySpeed:1,replayRequest:0};
