async function api(path,body,options={}){
  const guard=requests.capture(),token=options.anonymous?'':state.token;
  const {anonymous,...fetchOptions}=options;
  const controller=new AbortController(),tableCommand=body!==undefined&&/^\/api\/rooms\/[^/]+\/action$/.test(path);
  const abort=()=>controller.abort();
  if(options.signal?.aborted)abort();else options.signal?.addEventListener('abort',abort,{once:true});
  const timer=setTimeout(abort,API_TIMEOUT_MS);
  if(tableCommand)pendingTableRequests.add(controller);
  try{
    const response=await fetch(apiUrl(path),{method:body===undefined?'GET':'POST',headers:{...(token?{Authorization:`Bearer ${token}`} :{}),...(body===undefined?{}:{'Content-Type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)}),...fetchOptions,signal:controller.signal});
    guard.check();
    const data=await response.json().catch(error=>{if(controller.signal.aborted)throw error;return null;});guard.check();
    if(response.status===401&&token&&!/^\/api\/(account\/(login|register|recover|logout)$|session\/restore$)/.test(path))await expireIdentity(token);
    if(!response.ok){const e=new Error(data?.error||`请求暂时失败（${response.status}）`);e.status=response.status;throw e;}
    if(!data)throw new Error('服务器响应无法读取');return data;
  }catch(error){
    guard.check();
    if(controller.signal.aborted)throw Object.assign(new Error(tableCommand?'操作结果尚未确认，正在同步牌桌，请勿重复提交':'请求中断或超时，请稍后重试'),{resync:tableCommand});
    if(tableCommand&&!error.status)error.resync=true;
    throw error;
  }finally{
    clearTimeout(timer);pendingTableRequests.delete(controller);options.signal?.removeEventListener('abort',abort);
  }
}
function abortPendingTableRequests(){for(const controller of pendingTableRequests)controller.abort();}
function captureRoomChanges(previous,room){
  const same=previous?.code===room.code;
  if(!same){state.chatDraft='';state.chatUnread=0;state.chatOpen=false;state.reactions={};state.chatBusy=false;state.chatPending=null;}
  const oldMessages=new Set((same?previous.chat||[]:room.chat||[]).map(m=>m.id));
  const fresh=(room.chat||[]).filter(m=>!oldMessages.has(m.id));
  if(same){for(const m of fresh){if(m.playerId!==room.meId&&!state.chatOpen&&!state.chatMuted)state.chatUnread=Math.min(99,state.chatUnread+1);const age=Date.now()-Date.parse(m.at);if(age>=-30000&&age<8000&&!state.reactionsMuted)state.reactions[m.playerId]={...m,until:Date.now()+5000};}}
  state.motion=null;
  if(same&&room.hand&&state.animations){const a=previous.hand,b=room.hand;state.motion={hand:a?.id!==b.id,board:a?.id===b.id?(a.board||[]).length:0,newBoard:(b.board||[]).length>(a?.id===b.id?(a.board||[]).length:0),actor:b.status==='playing'&&(a?.id!==b.id||a.actingId!==b.actingId)?b.actingId:null,win:a?.id===b.id&&a.status!=='complete'&&b.status==='complete'};}
}
function normalizeState(room){if(!room||room.meId!==state.user?.id)return;const previous=state.room;if(previous?.code===room.code&&Number(previous.revision)>Number(room.revision))return;if(previous?.hand?.id!==room.hand?.id){if(state.modal?.kind==='show')closeModal();state.showHandId=null;state.revealed=new Set();state.raise=0;}captureRoomChanges(previous,room);state.room=room;const changed=rememberCommitment(room.hand);if(changed&&!state.commitmentMismatch)toast('发现同一手牌的发牌承诺发生变化，请停止操作并保存记录',true);state.commitmentMismatch=changed;if(room.serverTime){const t=typeof room.serverTime==='number'?room.serverTime:Date.parse(room.serverTime);if(Number.isFinite(t))state.timeOffset=t-Date.now();}const actions=room.actions||{};if(actions.canRaise){const min=Number(actions.minRaiseTo)||0,max=Number(actions.maxRaiseTo)||min;state.raise=Math.max(min,Math.min(max,state.raise||min));}render();}
async function command(type,payload={}){if(state.busy||!state.room)return;const code=state.room.code,guard=requests.capture();state.busy=true;render();try{const result=await api(`/api/rooms/${encodeURIComponent(code)}/action`,{type,...payload,commandId:commandId(),...(['fold','check','call','raise','allin'].includes(type)?{handId:state.room.hand?.id,actionSeq:state.room.hand?.actionSeq}:{})});guard.check();normalizeState(result.room||result);if(['approve','reject','sit','buyin','settings','transferHost'].includes(type))toast({approve:'已同意带入申请',reject:'已拒绝带入申请',sit:'入座申请已提交',buyin:'补码申请已提交',settings:'房间设置已保存',transferHost:'房主已转交'}[type]);return true;}catch(error){if(!error.stale&&guard.valid()){if(error.resync&&state.page==='room'&&state.room?.code===code&&navigator.onLine&&document.visibilityState!=='hidden')connectStream(code);toast(error.message,true);}return false;}finally{if(guard.valid()){state.busy=false;render();}}}
function stopStream(){state.stream?.abort();state.stream=null;clearTimeout(state.reconnectTimer);state.reconnectTimer=null;state.connected=false;}
async function connectStream(code,attempt=0){
  stopStream();
  const controller=new AbortController(),token=state.token;state.stream=controller;
  state.connection=attempt?'正在重连':'正在同步牌桌';updateConnection();
  let watchdog,lastMessage=Date.now();
  try{
    watchdog=setInterval(()=>{if(state.stream===controller&&Date.now()-lastMessage>45000)connectStream(code,attempt+1);},5000);
    const response=await fetch(apiUrl(`/api/events?room=${encodeURIComponent(code)}`),{headers:{Authorization:`Bearer ${token}`},signal:controller.signal,cache:'no-store'});
    if(controller.signal.aborted||state.stream!==controller)return;
    if(response.status===401){await expireIdentity(token);return;}
    if(!response.ok||!response.body)throw new Error('无法连接牌桌');
    const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';
    while(true){
      const {done,value}=await reader.read();
      if(controller.signal.aborted||state.stream!==controller)return;
      if(done)throw new Error('连接已中断');
      lastMessage=Date.now();buffer+=decoder.decode(value,{stream:true}).replace(/\r\n/g,'\n');
      if(buffer.length>2*1024*1024)throw new Error('牌桌更新过大，请重新连接');
      let end;
      while((end=buffer.indexOf('\n\n'))!==-1){
        const event=buffer.slice(0,end);buffer=buffer.slice(end+2);
        const data=event.split('\n').filter(line=>line.startsWith('data:')).map(line=>line.slice(5).trimStart()).join('\n');
        if(data){
          const incoming=JSON.parse(data);
          if(event.split('\n').some(line=>/^event:\s*session-expired$/.test(line))){await expireIdentity(token);return;}
          if(incoming.code===code&&state.page==='room'){
            state.connected=true;state.connection='实时连接';normalizeState(incoming);updateConnection();
          }
        }
      }
    }
  }catch(error){
    if(controller.signal.aborted||state.stream!==controller)return;
    controller.abort();state.connected=false;state.connection=navigator.onLine?'连接中断 · 正在重连':'网络已断开';updateConnection();
    if(state.page==='room'&&state.room?.code===code)state.reconnectTimer=setTimeout(()=>connectStream(code,attempt+1),Math.min(12000,1200*2**Math.min(attempt,4)));
  }finally{clearInterval(watchdog);}
}
function updateConnection(){document.querySelectorAll('[data-connection]').forEach(el=>el.innerHTML=`<i class="dot ${state.connected?'':'off'}"></i>${esc(state.connection)}`);document.querySelectorAll('[data-game-action]').forEach(el=>el.disabled=!state.connected||state.busy);}
async function loadMe(){const guard=requests.capture(),data=await api('/api/me');guard.check();state.user=data.user;state.stats=data.stats;state.rooms=data.rooms||[];state.createKeyRequired=Boolean(data.createKeyRequired);}
async function route(){requests.invalidate();const guard=requests.capture();stopStream();state.busy=false;closeModal();if(state.pendingRecovery){state.page='recovery';render();return;}const parts=location.hash.replace(/^#\/?/,'').split('/').map(p=>{try{return decodeURIComponent(p);}catch{return p;}});if(!state.user){state.page='welcome';render();return;}if(parts[0]==='room'&&parts[1]){state.page='loading';render();try{let room;if(parts[2]){const result=await api(`/api/rooms/${encodeURIComponent(parts[1])}/join`,{invite:parts[2]});room=result.room||result;}else room=await api(`/api/rooms/${encodeURIComponent(parts[1])}`);guard.check();state.page='room';normalizeState(room);connectStream(room.code);return;}catch(error){if(error.stale||!guard.valid())return;toast(error.message,true);state.page='lobby';state.room=null;render();return;}}state.room=null;state.page=parts[0]==='career'?'career':parts[0]==='hands'?'hands':'lobby';try{await loadMe();if(state.page==='career')state.stats=await api('/api/stats');if(state.page==='hands')await loadLibrary(true);guard.check();}catch(error){if(error.stale||!guard.valid())return;toast(error.message,true);}if(guard.valid())render();}
function navigate(hash=''){if(location.hash===`#${hash}`||(!hash&&!location.hash))route();else location.hash=hash;}
function header(){return `<header class="topbar"><button class="brand" data-action="lobby" aria-label="回到 BBPoker 大厅"><img src="/icon.svg" alt=""><strong>BB<span>Poker</span></strong></button>${state.user&&state.page!=='recovery'?`<nav class="topnav" aria-label="主导航">${btn('牌桌','lobby',state.page==='lobby'||state.page==='room'?'active':'')}${btn('牌谱','hands',state.page==='hands'?'active':'')}${btn('生涯','career',state.page==='career'?'active':'')}<button class="profile-btn" data-action="profile" aria-label="账号：${esc(state.user.name)}">${avatar(state.user)}<span class="profile-name">${esc(state.user.name)}</span></button></nav>`:btn('规则与隐私','fairness','ghost small')}</header>`;}
function patchFocusedChat(html){
  // Keep the actual input node attached during SSE updates, including Chinese IME.
  const next=document.createElement('div');next.innerHTML=html;
  const currentMain=app.querySelector('.room-shell'),nextMain=next.querySelector('.room-shell');
  const oldChat=app.querySelector('.chat-card'),newChat=next.querySelector('.chat-card');
  if(!currentMain||!nextMain||!oldChat||!newChat||currentMain.dataset.room!==nextMain.dataset.room)return false;
  app.querySelector('.topbar').replaceWith(next.querySelector('.topbar'));
  currentMain.querySelector('.room-head').replaceWith(nextMain.querySelector('.room-head'));
  currentMain.querySelectorAll(':scope > .room-notice').forEach(el=>el.remove());
  const grid=currentMain.querySelector('.game-grid');for(const note of nextMain.querySelectorAll(':scope > .room-notice'))currentMain.insertBefore(note,grid);
  currentMain.querySelector('.table-column').innerHTML=nextMain.querySelector('.table-column').innerHTML;
  for(const selector of ['.chat-heading','.chat-options','.emote-row','.chat-hint']){const old=oldChat.querySelector(selector),fresh=newChat.querySelector(selector);if(old&&fresh&&old.innerHTML!==fresh.innerHTML)old.innerHTML=fresh.innerHTML;}
  const oldMessages=oldChat.querySelector('.chat-messages'),newMessages=newChat.querySelector('.chat-messages');
  if(oldMessages&&newMessages){const ids=new Set([...newMessages.children].map(el=>el.dataset.message));for(const item of [...oldMessages.children])if(!ids.has(item.dataset.message)||!item.dataset.message)item.remove();const currentIds=new Set([...oldMessages.children].map(el=>el.dataset.message));for(const item of [...newMessages.children])if(!item.dataset.message||!currentIds.has(item.dataset.message))oldMessages.append(item);}
  const input=oldChat.querySelector('#chat-input'),freshInput=newChat.querySelector('#chat-input');
  if(input&&freshInput){input.disabled=freshInput.disabled;if(!state.composing&&input.value!==state.chatDraft)input.value=state.chatDraft;}
  const submit=oldChat.querySelector('[type=submit]'),freshSubmit=newChat.querySelector('[type=submit]');if(submit&&freshSubmit)submit.disabled=freshSubmit.disabled;
  const aside=currentMain.querySelector('.side-stack');for(const child of [...aside.children])if(child!==oldChat)child.remove();
  for(const child of [...nextMain.querySelector('.side-stack').children])if(child!==newChat)aside.append(child);
  return true;
}
function render(){
  if(state.composing&&document.activeElement?.id!=='chat-input'){state.renderDeferred=true;return;}
  const focused=document.activeElement,focusId=app.contains(focused)?focused.id:null;
  const selection=focusId&&typeof focused.selectionStart==='number'?[focused.selectionStart,focused.selectionEnd]:null;
  const scroll=$('#chat-messages'),scrollTop=scroll?.scrollTop||0,atBottom=!scroll||scroll.scrollHeight-scroll.scrollTop-scroll.clientHeight<45;
  const html=header()+({welcome:welcome,recovery:recoveryPage,loading:()=>'<div class="boot"><span class="spinner"></span><span>正在连接 BBPoker…</span></div>',error:errorPage,lobby:lobby,room:roomView,career:career,hands:handLibrary}[state.page]||lobby)();
  if(!(focusId==='chat-input'&&state.page==='room'&&patchFocusedChat(html)))app.innerHTML=html;
  const current=$('#chat-messages');if(current)current.scrollTop=atBottom?current.scrollHeight:scrollTop;
  if(focusId){const next=document.getElementById(focusId);if(next&&next!==focused){next.focus({preventScroll:true});if(selection)next.setSelectionRange(...selection);}}
  state.motion=null;state.renderDeferred=false;tick();
}
