function lobby(){const active=state.rooms.filter(r=>r.status!=='closed'),past=state.rooms.filter(r=>r.status==='closed');const roomList=rooms=>`<div class="room-list">${rooms.map(r=>`<button class="room-item" data-action="open-room" data-code="${esc(r.code)}"><span><strong>${esc(r.name)}</strong><small>${esc(r.code)} · ${r.status==='closed'?'已结束':r.status==='playing'?'正在进行':'等待入座'}</small></span><span class="muted">${r.status==='closed'?'查看记录':'进入牌桌'} ↗</span></button>`).join('')}</div>`;return `<main class="shell lobby-shell"><h1 class="page-title">牌桌</h1>${active.length?`<section class="panel active-rooms"><h2>当前牌桌</h2>${roomList(active)}</section>`:''}<section class="lobby-grid"><div class="panel create-panel"><h2>创建牌桌</h2><p class="subheading">设置盲注，邀请朋友。</p>${btn('创建牌桌','create','primary')}</div><div class="panel"><h2>加入牌桌</h2><form id="join-form" class="row join-form"><input aria-label="邀请链接" name="invite" placeholder="粘贴朋友的邀请链接" required autocomplete="off"><button class="outline" type="submit">加入</button></form></div></section>${past.length?`<details class="panel past-rooms"><summary>历史牌桌 <span class="muted">${past.length}</span></summary>${roomList(past)}</details>`:''}<footer class="footer"><span>朋友积分局</span><div class="row">${btn('玩法规则','rules')}${btn('公平与隐私','fairness')}</div></footer></main>`;}
const emotes={nice:{symbol:'👏',label:'好牌'},gg:{symbol:'🤝',label:'好局'},lol:{symbol:'😄',label:'哈哈'},wow:{symbol:'😮',label:'哇'},thanks:{symbol:'🙏',label:'谢谢'},unlucky:{symbol:'😅',label:'差一点'}};
function reactionBubble(id){const r=state.reactions[id];if(!r||r.until<Date.now()||state.reactionsMuted)return '';const e=emotes[r.emote];return `<div class="seat-reaction" data-reaction-until="${r.until}">${r.kind==='emote'&&e?`${e.symbol} ${e.label}`:esc(r.text)}</div>`;}
function chatPanel(room){const messages=state.chatMuted?[]:(room.chat||[]).slice(-100);return `<section class="panel chat-card ${state.chatOpen?'is-open':''}"><button class="chat-heading" data-action="toggle-chat" aria-expanded="${state.chatOpen}" aria-controls="chat-content"><span><span aria-hidden="true">◌</span> 牌桌聊天 ${state.chatUnread?`<b class="unread">${state.chatUnread}</b>`:''}</span><span class="muted">${state.chatOpen?'收起':'展开'}</span></button>${state.chatOpen?`<div id="chat-content"><div class="chat-options">${btn(state.chatMuted?'显示聊天':'隐藏聊天','mute-chat','ghost small',`aria-pressed="${state.chatMuted}"`)}${btn(state.reactionsMuted?'显示气泡':'隐藏气泡','mute-reactions','ghost small',`aria-pressed="${state.reactionsMuted}"`)}</div><div id="chat-messages" class="chat-messages" role="log" aria-label="本桌聊天">${messages.length?messages.map(m=>`<div class="chat-message ${m.playerId===room.meId?'self':''}" data-message="${esc(m.id)}"><div class="chat-byline"><b>${esc(m.name)}</b><time>${esc(new Date(m.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}))}</time></div><p>${m.kind==='emote'&&emotes[m.emote]?`${emotes[m.emote].symbol} ${emotes[m.emote].label}`:esc(m.text)}</p></div>`).join(''):`<p class="chat-empty">${state.chatMuted?'已隐藏聊天内容':'和这桌朋友聊两句'}</p>`}</div><div class="emote-row" aria-label="快捷表情">${Object.entries(emotes).map(([id,e])=>btn(e.symbol,'send-emote','emote-btn',`data-emote="${id}" title="${e.label}" aria-label="发送表情：${e.label}" ${state.chatBusy||room.status==='closed'?'disabled':''}`)).join('')}</div><form id="chat-form" class="chat-compose"><input id="chat-input" name="text" maxlength="160" autocomplete="off" placeholder="聊两句…" aria-label="聊天消息，最多160字" value="${esc(state.chatDraft)}" ${room.status==='closed'?'disabled':''}><button class="primary" type="submit" ${state.chatBusy||room.status==='closed'?'disabled':''}>发送</button></form><small class="chat-hint">${room.status==='closed'?'本桌已结束':'仅本桌成员可见 · 最近 100 条'}</small></div>`:''}</section>`;}
async function sendChat(kind,textOrEmote){
  const room=state.room;if(!room||state.chatBusy)return;
  const text=String(textOrEmote||'').trim();if(kind==='text'&&!text)return;
  const guard=requests.capture(),code=room.code,draft=state.chatDraft;const previous=state.chatPending;const pending=previous?.code===code&&previous.kind===kind&&previous.content===text?previous:{code,kind,content:text,messageId:commandId()};state.chatPending=pending;state.chatBusy=true;render();
  try{await api(`/api/rooms/${encodeURIComponent(code)}/chat`,{kind,...(kind==='text'?{text}:{emote:text}),messageId:pending.messageId});guard.check();if(state.room?.code!==code)return;state.chatPending=null;if(kind==='text'&&state.chatDraft===draft)state.chatDraft='';}
  catch(error){if(!error.stale&&guard.valid())toast(error.message,true);}
  finally{if(guard.valid()&&state.room?.code===code){state.chatBusy=false;render();}}
}
async function loadLibrary(reset=false){
  const library=state.library;if(library.loading&&!reset)return;
  const id=++library.request,guard=requests.capture();library.loading=true;library.error='';
  if(reset){library.hands=[];library.nextCursor=null;}render();
  const query=new URLSearchParams({limit:'20'});if(!reset&&library.nextCursor)query.set('before',library.nextCursor);if(library.favorites)query.set('favorites','1');if(library.room)query.set('room',library.room);
  try{const data=await api(`/api/hands?${query}`);guard.check();if(id!==state.library.request)return;const seen=new Set(library.hands.map(h=>h.id));library.hands.push(...data.hands.filter(h=>!seen.has(h.id)));library.nextCursor=data.nextCursor||null;}
  catch(error){if(!error.stale&&guard.valid()&&id===state.library.request)library.error=error.message;}
  finally{if(guard.valid()&&id===state.library.request){library.loading=false;render();}}
}
function handLibrary(){const l=state.library;return `<main class="shell library-shell"><div class="section-head"><div><h1 class="page-title">我的牌谱</h1><p class="subheading">每手结束自动保存，随时回来复盘。</p></div>${btn('导出','export','outline')}</div><div class="library-filters"><div class="segmented">${btn('全部','library-all',!l.favorites?'active':'')}${btn('★ 收藏','library-favorites',l.favorites?'active':'')}</div><label class="sr-only" for="library-room">按牌桌筛选</label><select id="library-room"><option value="">所有牌桌</option>${state.rooms.map(r=>`<option value="${esc(r.code)}" ${l.room===r.code?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div>${l.error?`<div class="panel empty"><p>${esc(l.error)}</p>${btn('重试','library-retry','outline small')}</div>`:l.hands.length?`<div class="hand-library">${l.hands.map(handSummary).join('')}</div>`:!l.loading?'<div class="panel empty"><span class="empty-symbol">♧</span><h3>'+ (l.favorites?'还没有收藏的牌谱':'还没有完成的牌局')+'</h3><p>'+(l.favorites?'点击牌谱旁的星标，把想复盘的手牌留在这里。':'完成第一手后，记录会自动出现在这里。')+'</p></div>':''}<div class="load-more">${l.loading?'<span class="spinner"></span><span>正在读取牌谱…</span>':l.nextCursor?btn('加载更多','library-more','outline'):l.hands.length?'<span>已显示全部记录</span>':''}</div><p class="privacy-footnote">只显示你的底牌与已经公开的牌；未公开的底牌始终隐藏。</p></main>`;}
function handSummary(h){const net=Number(h.net||0)+Number(h.miniNet||0);return `<article class="hand-record"><button class="hand-open" data-action="replay" data-hand="${esc(h.id)}" data-room="${esc(h.roomCode)}"><div class="hand-record-title"><strong>第 ${num(h.number)} 手</strong><small>${esc(h.roomName)} · ${esc(fmtDate(h.at))}</small></div><div class="hand-record-cards"><div class="record-hole">${cards(h.cards||[null,null],'small-card')}</div><span class="card-separator"></span><div class="record-board">${Array.from({length:5},(_,i)=>card(h.board?.[i],'mini',!h.board?.[i])).join('')}</div></div><div class="hand-record-result"><b class="${profitClass(net)}">${signed(net)}</b><small>回放 →</small></div></button>${btn(h.favorite?'★':'☆','favorite',`favorite-btn ${h.favorite?'is-favorite':''}`,`data-hand="${esc(h.id)}" data-favorite="${!h.favorite}" aria-label="${h.favorite?'取消收藏':'收藏这手牌'}" aria-pressed="${Boolean(h.favorite)}"`)}</article>`;}
async function favoriteHand(id,favorite,button){const guard=requests.capture();button.disabled=true;try{const result=await api(`/api/hands/${encodeURIComponent(id)}/favorite`,{favorite});guard.check();const item=state.library.hands.find(h=>h.id===id);if(item)item.favorite=result.favorite;if(state.library.favorites&&!result.favorite)state.library.hands=state.library.hands.filter(h=>h.id!==id);if(state.replay?.hand.id===id)state.replay.favorite=result.favorite;render();if(state.modal?.kind==='replay')renderReplay();}catch(error){if(!error.stale)toast(error.message,true);}finally{if(button.isConnected)button.disabled=false;}}
const layouts={2:[[50,94],[50,9]],3:[[50,94],[12,29],[88,29]],4:[[50,94],[6,51],[50,9],[94,51]],5:[[50,94],[7,68],[23,13],[77,13],[93,68]],6:[[50,94],[7,72],[8,28],[50,7],[92,28],[93,72]],7:[[50,95],[10,78],[5,45],[28,9],[72,9],[95,45],[90,78]],8:[[50,95],[12,82],[4,52],[13,22],[50,6],[87,22],[96,52],[88,82]],9:[[50,95],[12,81],[4,51],[13,22],[35,5],[65,5],[87,22],[96,51],[88,81]]};
function seatView(index,room){const player=room.players.find(p=>p.seat===index),mine=room.players.find(p=>p.id===room.meId),n=room.settings.maxPlayers,relative=(index-(mine?.seat??0)+n)%n,[x,y]=(layouts[n]||layouts[9])[relative],hand=room.hand,isMe=player?.id===room.meId;const style=`left:${x}%;top:${y}%`;if(!player)return `<div class="seat" style="${style}">${btn(`<span>＋</span>${room.status==='closed'?'已结束':mine?.seat!=null?'空座':`${index+1} 号座`}`,'sit','empty-seat',`data-seat="${index}" ${room.status==='closed'||mine?.seat!=null?'disabled':''}`)}</div>`;const isWinner=hand?.status==='complete'&&(hand.result?.mainWinnerIds||[]).includes(player.id),isActor=hand?.status==='playing'&&hand.actingId===player.id;let label=player.sittingOut?'暂离':!player.connected?'离线':player.allIn?'ALL IN':player.folded?'已弃牌':player.lastAction?formatAction(player.lastAction):isMe?'你的座位':'已入座';if(isWinner)label='赢得主池';const pending=room.pending?.some(p=>p.playerId===player.id);if(pending)label='等待带入审批';return `<div class="seat ${isMe?'mine':''} ${player.folded&&hand?.status==='playing'?'folded':''} ${isActor?'acting':''}" style="${style}"><div class="seat-main ${state.motion?.actor===player.id?'turn-enter':''} ${isWinner&&state.motion?.win?'win-enter':''}">${avatar(player,'')}${player.inHand&&player.cards?.length?`<div class="hole-cards">${cards(player.cards,state.motion?.hand?'mini card-enter':'mini')}</div>`:''}<div class="seat-label">${hand&&hand.buttonSeat===index?'<b title="庄家">D</b>':''}${hand&&hand.smallBlindSeat===index?'<b class="blind" title="小盲">SB</b>':''}${hand&&hand.bigBlindSeat===index?'<b class="blind" title="大盲">BB</b>':''}${player.squidWon?'<b title="鱿鱼标记">✓</b>':''}</div><div class="name">${esc(player.name)}${player.id===room.hostId?' · 房主':''}</div><div class="stack-value">${num(player.stack)}</div><div class="seat-status ${isWinner?'winner':''}">${esc(label)}</div></div>${reactionBubble(player.id)}${Number(player.bet)>0&&hand?.status==='playing'?`<span class="bet-chip">${num(player.bet)}</span>`:''}</div>`;}
function formatAction(action){if(typeof action==='object')return eventText(action);return ({fold:'弃牌',check:'过牌',call:'跟注',raise:'加注',allin:'ALL IN',sitout:'暂离',smallBlind:'小盲',bigBlind:'大盲',small_blind:'小盲',big_blind:'大盲',ante:'前注'})[action]||String(action||'');}
function tableCenter(room){const hand=room.hand;if(!hand)return `<div class="table-center"><div class="table-idle"><strong>${room.status==='closed'?'牌桌已结束':'等待入座'}</strong><p>${room.status==='closed'?'可查看历史牌局。':room.players.some(p=>p.id===room.meId&&p.seat!=null)?'等待朋友入座。':'点击空座入座。'}</p>${room.status==='closed'?btn('回顾牌局','history','outline'):btn('邀请朋友','invite','outline')}</div></div>`;const winners=(hand.result?.mainWinnerIds||[]).map(id=>room.players.find(p=>p.id===id)?.name||'牌友');return `<div class="table-center"><div class="pot-label">${hand.status==='complete'?'本手底池':'底池积分'}</div><div class="pot-amount">${num(hand.pot??hand.result?.pots?.reduce((sum,p)=>sum+p.amount,0))}</div><div class="board">${Array.from({length:5},(_,i)=>card(hand.board?.[i],state.motion?.newBoard&&i>=state.motion.board?'card-enter':'',!hand.board?.[i])).join('')}</div>${hand.status==='complete'?`<div class="hand-result ${state.motion?.win?'win-enter':''}"><p class="result-title">${winners.length?`${esc(winners.join('、'))}${winners.length>1?' 平分主池':' 赢得主池'}`:'本手已结束'}</p><span>第 ${num(hand.number)} 手 · 等待下一手</span></div>`:`<div class="street-label">第 ${num(hand.number)} 手 · ${esc(streetNames[hand.street]||hand.street)}</div>`}</div>`;}
function roomView(){const room=state.room;if(!room)return errorPage();const me=room.players.find(p=>p.id===room.meId),host=room.hostId===room.meId,hand=room.hand,playing=hand?.status==='playing',closed=room.status==='closed';return `<main class="room-shell" data-room="${esc(room.code)}"><div class="room-head"><div><h2>${esc(room.name)}</h2><div class="room-meta"><span>${esc(room.code)}</span><span>·</span><span>${num(room.settings.smallBlind)} / ${num(room.settings.bigBlind)}</span><span>·</span><span data-connection><i class="dot ${state.connected?'':'off'}"></i>${esc(state.connection)}</span></div></div><div class="room-head-tools">${btn('邀请 ↗','invite','outline',closed?'disabled':'')}${btn('···','room-menu','icon-btn','aria-label="房间菜单"')}</div></div>${state.commitmentMismatch?'<div class="room-notice negative" role="alert" style="border-color:#e4958970;background:#e4958912;color:#e49589">⚠ 同一手牌的发牌承诺与本机此前收到的不同。请暂停参与，保存导出记录并检查服务器。</div>':''}${closed?'<div class="room-notice">牌桌已结束。积分已结算，你可以继续查看和导出自己的牌局记录。</div>':''}${(room.messages||[]).slice(-2).map(m=>`<div class="room-notice">${esc(m)}</div>`).join('')}<div class="game-grid"><section class="table-column"><div class="mini-strip"><span class="badge">${room.players.filter(p=>p.seat!=null).length} / ${room.settings.maxPlayers} 人入座</span><span class="badge">${room.settings.approvalRequired?'房主审核带入':'自由带入'}</span>${room.settings.squid?`<span class="badge">鱿鱼 · ${num(room.settings.squidUnit)} 分</span>`:''}${room.settings.mushroom?`<span class="badge">蘑菇池 · ${num(room.mini?.mushroom?.pool)} 分</span>`:''}</div><div class="table-stage" aria-label="德州牌桌"><div class="felt"><span class="felt-mark" aria-hidden="true">BBPoker</span></div>${tableCenter(room)}${Array.from({length:room.settings.maxPlayers},(_,i)=>seatView(i,room)).join('')}</div><div class="table-bottom">${actionArea(room,me,host)}${me?.seat!=null&&!closed?`<div class="seat-actions">${btn('补充积分','buyin','ghost',playing?'disabled':'')}${btn(me.sittingOut?'回到牌桌':'暂离','sitout','ghost',playing?'disabled':'')}${btn('离开座位','stand','ghost',playing?'disabled':'')}${hand?.status==='complete'&&me.inHand?btn('主动亮牌','show','outline'):''}</div>`:''}</div></section><aside class="side-stack">${chatPanel(room)}${host&&room.pending?.length?`<div class="panel host-panel"><h3 style="margin-bottom:13px">带入申请 <span class="gold">${room.pending.length}</span></h3>${room.pending.map(p=>`<div class="approval"><p><b>${esc(p.name)}</b> 申请 ${num(p.amount)} 积分<br><span class="muted">${Number(p.seat)+1} 号座</span></p><div class="row">${btn('同意','approve','primary small',`data-request="${esc(p.id)}" ${state.busy?'disabled':''}`)}${btn('拒绝','reject','ghost small',`data-request="${esc(p.id)}" ${state.busy?'disabled':''}`)}</div></div>`).join('')}</div>`:''}${room.settings.squid||room.settings.mushroom?`<div class="panel mini-panel"><h3>小游戏</h3>${miniPanel(room)}</div>`:''}<div class="panel"><h3>我的本场</h3><div class="data-row"><span>累计带入</span><strong>${num(me?.totalBuyIn)}</strong></div><div class="data-row"><span>本场净积分</span><strong class="${profitClass(me?.sessionProfit)}">${signed(me?.sessionProfit)}</strong></div>${me?.squidReserve?`<div class="data-row"><span>鱿鱼预留</span><strong>${num(me.squidReserve)}</strong></div>`:''}<div class="divider" style="margin:14px 0"></div><div class="row wrap">${btn('本桌牌谱','history','outline small')}${btn('上一手','last-hand','ghost small',!hand||hand.number<1?'disabled':'')}</div></div>${hand?.log?.length?`<details class="panel activity-panel" id="table-activity" ${state.activityOpen?'open':''}><summary>牌桌动态</summary><div class="activity-list">${hand.log.slice(-7).reverse().map(e=>`<div>${esc(eventText(e,room.players))}</div>`).join('')}</div></details>`:''}</aside></div></main>`;}
function miniPanel(room){let html='';const squid=room.mini?.squid,mush=room.mini?.mushroom;if(room.settings.squid){const participants=squid?.participants||[],won=Array.isArray(squid?.won)?squid.won:Object.keys(squid?.won||{}).filter(k=>squid.won[k]);html+=`<div class="mini-status"><strong>鱿鱼游戏 <span class="gold">${squid?.active?`第 ${squid.round} 轮`:'等待新一轮'}</span></strong><p>${squid?.active?`${won.length} / ${participants.length} 人已获标记。轮内锁定座位，可在两手间补码。`:'至少 3 人，固定本轮玩家。最后一名未获标记者向其他人各付约定积分。'}</p></div>`;}if(room.settings.mushroom)html+=`<div class="mini-status"><strong>蘑菇池 <span class="gold">${num(mush?.pool)} 积分</span></strong><p>每人 ${num(room.settings.mushroomUnit)} 分，小盲额外一份。小盲独赢主池时收取蘑菇池。</p></div>`;return html;}
function actionArea(room,me,host){const hand=room.hand,a=room.actions||{},playing=hand?.status==='playing',closed=room.status==='closed',pending=room.pending?.find(p=>p.playerId===room.meId),eligible=room.players.filter(p=>p.seat!=null&&!p.sittingOut&&p.stack>0).length;const cardSummary=`<div class="my-hand-summary"><small>${me?.inHand?'你的手牌':'你的座位'}</small><div class="my-cards">${me?.inHand?cards(me.cards||[null,null]):`<span class="muted" style="font-size:13px">${me?.seat!=null?`${me.seat+1} 号座`:'观战中'}</span>`}</div></div>`;if(a.canAct&&playing){const disabled=state.busy||!state.connected?'disabled':'';return `<div class="action-area">${cardSummary}<div class="decision"><div class="turn-row"><span>轮到你了${a.callAmount?` · 需跟 ${num(a.callAmount)}`:' · 可以过牌'}</span><b class="clock" id="clock"></b></div><div class="action-buttons">${a.canFold?btn('弃牌','fold','',`data-game-action ${disabled}`):''}${a.canCheck?btn('过牌','check','outline',`data-game-action ${disabled}`):btn(`跟 ${num(a.callAmount)}`,'call','outline',`data-game-action ${disabled}`)}${a.canRaise?btn(`加至 ${num(state.raise)}`,'raise','primary',`data-game-action id="raise-button" ${disabled}`):a.canAllIn?btn('全下','allin','gold-button all-in',`data-game-action ${disabled}`):''}</div>${a.canRaise?`<div class="raise-controls"><input aria-label="加注至总额" type="range" id="raise-range" min="${a.minRaiseTo}" max="${a.maxRaiseTo}" step="1" value="${state.raise}"><input aria-label="加注总额" type="number" id="raise-input" min="${a.minRaiseTo}" max="${a.maxRaiseTo}" step="1" value="${state.raise}"></div><div class="raise-shortcuts">${[['最小','min'],['半池','half'],['底池','pot'],['全下','all']].map(([label,value])=>btn(label,'raise-preset','',`data-preset="${value}"`)).join('')}</div>`:''}</div></div>`;}let text=closed?'这一桌已经结束。':pending?`已申请带入 ${num(pending.amount)} 积分，等待房主确认。`:playing?(me?.folded?'本手已弃牌，等待下一手。':me?.allIn?'你已全下，等待公共牌。':`等待 ${room.players.find(p=>p.id===hand.actingId)?.name||'牌友'} 行动`):me?.sittingOut?'你正在暂离，回到牌桌后可参与下一手。':hand?.status==='complete'?'本手已结束，可以主动亮牌或补充积分。':'至少 2 人入座后可开始。';return `<div class="action-area">${cardSummary}<div class="inactive-actions"><p>${esc(text)}${playing?'<br><span class="clock" id="clock"></span>':''}</p><div class="row">${!playing&&!closed&&host?btn(hand?'发下一手':'开始第一手','start','primary',`${eligible<2||state.busy?'disabled':''}`):!playing&&!closed&&!host?'<span class="badge">由房主开始</span>':''}${closed?btn('查看牌局','history','outline small'):''}${!me?.inHand&&!playing&&me?.seat==null&&!pending&&!closed?btn('选择座位','choose-seat','outline small'):''}</div></div></div>`;}
function career(){const s=state.stats||{};return `<main class="shell"><div class="row between"><h1 class="page-title">我的生涯</h1></div><div class="stats-grid">${[['累计净积分',signed(s.net),profitClass(s.net)],['完成手数',num(s.hands),''],['获分手数',num(s.wins),''],['到达摊牌',num(s.showdowns),'']].map(([label,value,cls])=>`<div class="stat"><small>${label}</small><strong class="${cls}">${value}</strong></div>`).join('')}</div><section class="panel"><div class="section-head"><div><h3>积分足迹</h3><p class="subheading">按已结算牌局记录，小游戏收益单独列示。</p></div>${btn('导出我的记录','export','outline small')}</div>${curveChart(s.curve||[])}<div class="career-meta"><div><b class="${profitClass(s.holdemNet)}">${signed(s.holdemNet)}</b><small>德州净积分</small></div><div><b class="${profitClass(s.miniNet)}">${signed(s.miniNet)}</b><small>小游戏净积分</small></div><div><b>${Number(s.vpip||0).toFixed(1)}%</b><small>自愿入池 VPIP</small></div><div><b>${Number(s.pfr||0).toFixed(1)}%</b><small>翻前加注 PFR</small></div></div></section><details class="help-details"><summary>指标说明</summary><p class="note">净积分不包含带入和补码。获分手数包含主池、边池和平分获分。VPIP / PFR 仅按实际参与手数计算；样本较少时波动较大。</p></details></main>`;}
function curveChart(curve){if(!curve.length)return '<div class="empty" style="padding:50px 15px"><div>暂无记录</div><p>完成对局后显示积分曲线。</p></div>';const values=curve.map(v=>Number(v.net)||0),min=Math.min(0,...values),max=Math.max(1,...values),span=max-min||1,width=700,height=180,x=i=>curve.length===1?350:22+i*(width-44)/(curve.length-1),y=v=>height-20-(v-min)/span*(height-35),points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');return `<div class="chart" aria-label="${curve.length} 手牌的累计积分曲线"><svg viewBox="0 0 ${width} ${height}" role="img"><title>积分记录，最近为 ${signed(values.at(-1))}</title><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#187563" stop-opacity=".16"/><stop offset="100%" stop-color="#187563" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(t=>`<line x1="20" y1="${20+t*(height-40)}" x2="680" y2="${20+t*(height-40)}" stroke="#dae3dc" stroke-dasharray="3 6"/>`).join('')}<line x1="20" y1="${y(0)}" x2="680" y2="${y(0)}" stroke="#b8c6bd"/><polygon points="${x(0)},${height} ${points} ${x(values.length-1)},${height}" fill="url(#chart-fill)"/><polyline points="${points}" fill="none" stroke="#187563" stroke-width="2.5" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="${i===values.length-1?4:2}" fill="#187563"><title>${esc(fmtDate(curve[i].at))} · ${signed(v)} 积分</title></circle>`).join('')}<text x="23" y="13" fill="#6e8175" font-size="10">${num(max)}</text><text x="23" y="177" fill="#6e8175" font-size="10">${num(min)}</text></svg></div>`;}
function tick(){document.querySelectorAll('[data-reaction-until]').forEach(el=>{if(Number(el.dataset.reactionUntil)<=Date.now())el.remove();});const el=$('#clock');if(!el||!state.room?.deadline)return;const raw=state.room.deadline,deadline=typeof raw==='number'?raw:Date.parse(raw);const remaining=Math.max(0,Math.ceil((deadline-Date.now()-state.timeOffset)/1000));el.textContent=`${remaining}s${remaining===0?' · 等待结算':''}`;el.classList.toggle('urgent',remaining<=8);}
setInterval(tick,400);
function openModal(title,body,kind='custom'){clearInterval(state.replayTimer);state.modal={kind,title};dialog.innerHTML=`<header class="modal-head"><h2>${title}</h2>${btn('×','close-modal','icon-btn ghost','aria-label="关闭窗口"')}</header><div class="modal-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function closeModal(){state.replayRequest++;clearInterval(state.replayTimer);state.replayTimer=null;state.modal=null;if(dialog.open)dialog.close();dialog.innerHTML='';}
dialog.addEventListener('cancel',event=>{event.preventDefault();closeModal();});
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();}});
function settingFields(settings,{roomName}={}){const s={...defaults,...settings};const numberField=(label,name,min,max,step=1,disabled=false)=>`<label class="field">${label}<input name="${name}" type="number" value="${s[name]}" min="${min}" max="${max}" step="${step}" ${disabled?'disabled':''} required></label>`;return `<div class="field-grid">${numberField('小盲积分','smallBlind',1,1000)}${numberField('大盲积分','bigBlind',s.smallBlind*2,2000)}</div><div class="form-section mini-options"><label class="toggle"><span>鱿鱼<small>至少 3 人，最后未获标记者支付积分</small></span><input name="squid" type="checkbox" data-mini-toggle="squid-options" ${s.squid?'checked':''}></label><div id="squid-options" class="mini-config" ${s.squid?'':'hidden'}>${numberField('鱿鱼每人支付积分','squidUnit',1,10000,1,!s.squid)}</div><label class="toggle"><span>蘑菇池<small>每手累积，小盲独赢主池时领取</small></span><input name="mushroom" type="checkbox" data-mini-toggle="mushroom-options" ${s.mushroom?'checked':''}></label><div id="mushroom-options" class="mini-config" ${s.mushroom?'':'hidden'}>${numberField('蘑菇池每份积分','mushroomUnit',1,10000,1,!s.mushroom)}</div></div><details class="form-section more-settings"><summary>更多设置</summary><div class="field-grid">${roomName!==undefined?`<label class="field full">牌桌名称<input name="name" maxlength="32" value="${esc(roomName)}" required></label>`:''}${numberField('最低带入','minBuyIn',s.bigBlind*10,1000000)}${numberField('最高带入','maxBuyIn',s.minBuyIn,1000000)}<label class="field">座位人数<select name="maxPlayers">${Array.from({length:8},(_,i)=>i+2).map(n=>`<option ${n===s.maxPlayers?'selected':''} value="${n}">${n} 人桌</option>`).join('')}</select></label>${numberField('行动时间（秒）','actionSeconds',15,90)}</div><label class="toggle"><span>房主审核带入<small>入座与补码需房主确认</small></span><input name="approvalRequired" type="checkbox" ${s.approvalRequired?'checked':''}></label></details><p class="settings-overview note" data-settings-overview>${s.maxPlayers} 人桌 · 带入 ${num(s.minBuyIn)}–${num(s.maxBuyIn)} · ${s.actionSeconds} 秒 · ${s.approvalRequired?'房主审核':'自由带入'}</p>`;}
function updateSettingConstraints(form){if(!form?.matches('#create-form,#settings-form'))return;const field=name=>form.elements.namedItem(name);field('bigBlind').min=String(Math.max(2,Number(field('smallBlind').value)*2));field('minBuyIn').min=String(Math.max(20,Number(field('bigBlind').value)*10));field('maxBuyIn').min=String(Math.max(1,Number(field('minBuyIn').value)));}
function inactiveSettingValue(input,fallback){const n=Number(input.value);return input.value!==''&&Number.isSafeInteger(n)&&n>=Number(input.min)&&n<=Number(input.max)?n:Number(input.defaultValue||fallback);}
function readSettings(form){const fd=new FormData(form),s={};for(const key of Object.keys(defaults)){const input=form.elements.namedItem(key);s[key]=typeof defaults[key]==='boolean'?fd.get(key)==='on':input?.disabled?inactiveSettingValue(input,defaults[key]):Number(fd.get(key));}return s;}
function createModal(){openModal('创建牌桌',`<form id="create-form">${settingFields(defaults,{roomName:state.user.name+'的朋友局'})}${state.createKeyRequired?'<label class="field form-section">建房口令<input name="createKey" type="password" autocomplete="off" placeholder="请向房主索取" required></label>':''}<div class="modal-footer">${btn('取消','close-modal','ghost')}<button class="primary" type="submit">创建牌桌</button></div></form>`,'create');}
function joinInvite(value){navigate(parseInvite(value));}
function buyinModal(seat){const r=state.room,isSit=seat!==undefined,me=r.players.find(p=>p.id===r.meId);if(!isSit&&me?.seat==null){toast('先选择一个空座位');return;}const min=isSit?r.settings.minBuyIn:1,max=r.settings.maxBuyIn-(me?.stack||0);if(max<min)return toast('当前积分已达到带入上限，无需补码');const approval=r.settings.approvalRequired&&r.hostId!==r.meId;openModal(isSit?`入座 · ${Number(seat)+1} 号座`:'补充积分',`<form id="buyin-form" data-seat="${isSit?seat:''}"><p class="note">${approval?'需房主确认。':'立即生效。'}</p><label class="field">${isSit?'带入':'补充'}积分<input name="amount" type="number" min="${min}" max="${max}" step="1" value="${Math.min(max,Math.max(min,r.settings.bigBlind*100))}" required></label><p class="note" style="margin-top:9px">允许范围 ${num(min)}–${num(max)} 积分</p><div class="modal-footer">${btn('取消','close-modal','ghost')}<button class="primary" type="submit">${approval?'申请带入':'确认带入'}</button></div></form>`,'buyin');}
function inviteModal(){const url=inviteUrl(state.room);openModal('邀请朋友',`<p class="note">持有链接的人可加入，请只发给本局朋友。</p><label class="field">邀请链接<textarea id="invite-link" readonly>${esc(url)}</textarea></label><div class="modal-footer">${canShare()?btn('分享','share-invite','outline'):''}${btn('复制链接','copy-invite','primary')}</div>`,'invite');}
async function copy(text,success='已复制'){try{await navigator.clipboard.writeText(text);toast(success);}catch{const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';(dialog.open?dialog:document.body).append(input);input.select();try{if(!document.execCommand('copy'))throw Error();toast(success);}catch{toast('请长按链接或恢复码手动复制');}input.remove();}}
function profileModal(){const account=state.user.username;openModal('我的账号',`<div class="row" style="margin-bottom:22px">${avatar(state.user,'large')}<div><h2>${esc(state.user.name)}</h2><p class="subheading">${account?`账号：${esc(account)}`:'原有昵称身份'}</p></div></div>${account?`<p class="note">用账号和密码可在其他设备登录，牌谱和积分记录会保留。忘记密码时使用注册时保存的找回码。</p>${btn('修改密码','change-password','outline')}`:`<p class="note">设置账号和密码后，继续保留现在的牌谱、积分和牌桌。</p>${btn('设置账号密码','bind-account','primary')}<details class="help-details"><summary>保存旧身份恢复码</summary><p class="note">仅用于尚未设置账号的旧身份。设置账号后此码失效。不要发给别人。</p><div class="recovery">${esc(state.token)}</div>${btn('复制旧恢复码','copy-token','outline small')}</details>`}<div class="divider"></div><div class="row wrap">${state.install?btn('添加到主屏幕','install','outline small'):''}${btn('退出当前设备','logout-confirm','danger small')}</div>`,'profile');}
function bindAccountModal(){openModal('设置账号密码',`<form id="bind-account-form" class="stack"><p class="note">保留当前身份的全部牌谱和积分。设置后用账号密码登录。</p>${usernameField()}${passwordField('password','密码',true)}<button type="submit" class="primary">保存账号</button></form>`,'bind-account');}
function changePasswordModal(){openModal('修改密码',`<form id="password-form" class="stack">${usernameField(state.user.username,true)}${passwordField('currentPassword','当前密码')}${passwordField('newPassword','新密码',true)}<p class="note">修改后其他设备会退出登录，并生成新的找回码。</p><button type="submit" class="primary">修改密码</button></form>`,'password');}
function recoverModal(){openModal('找回密码',`<form id="recover-form" class="stack"><p class="note">输入注册时保存的找回码。此版本不使用手机短信或邮箱找回。</p>${usernameField()}<label class="field">找回码<input name="recoveryCode" type="password" autocomplete="off" autocapitalize="none" spellcheck="false" required></label>${passwordField('newPassword','新密码',true)}<button type="submit" class="primary">设置新密码</button></form>`,'recover');}
function restoreModal(){openModal('找回旧昵称身份',`<form id="restore-form"><p class="note">只适用于以前没有设置账号的昵称身份。已设置账号请用账号密码登录。</p><label class="field">旧身份恢复码<textarea name="token" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="粘贴以前保存的完整恢复码" required></textarea></label><div class="modal-footer">${btn('取消','close-modal','ghost')}<button type="submit" class="primary">恢复旧身份</button></div></form>`,'restore');}
async function acceptAccount(data){await adoptIdentity(data);if(data.recoveryCode)state.pendingRecovery={code:data.recoveryCode,username:data.user.username};await route();}
async function submitAccount(kind,fd){const changing=kind==='bind'||kind==='password';if(changing){requests.invalidate();abortPendingTableRequests();stopStream();}const guard=requests.capture();const body={username:String(fd.get('username')||'').trim()};if(kind==='password'){delete body.username;body.currentPassword=String(fd.get('currentPassword')||'');body.newPassword=String(fd.get('newPassword')||'');}else if(kind==='recover'){body.recoveryCode=String(fd.get('recoveryCode')||'').trim();body.newPassword=String(fd.get('newPassword')||'');}else{body.password=String(fd.get('password')||'');if(kind==='register')body.name=String(fd.get('name')||'').trim()||body.username.slice(0,18);}try{const data=await api(`/api/account/${kind}`,body,{anonymous:!changing});guard.check();await acceptAccount(data);}catch(error){if(changing&&guard.valid())resumeTable();throw error;}}
async function logout(){const token=state.token,user=state.user,account=user?.username;stopStream();try{if(account)await api('/api/account/logout',{});}catch(error){if(error.status!==401){resumeTable();throw error;}}if(state.token!==token)return;resetPrivateView();const guard=requests.capture();state.token='';state.user=null;state.authMode='login';state.page='loading';render();try{await clearIdentity(token);}catch{if(!guard.valid())return;if(!account){state.token=token;state.user=user;state.page='lobby';render();throw new Error('本设备暂时无法清除旧身份，请重试退出');}toast('本设备未能清除缓存，请关闭页面；此登录已退出',true);}if(guard.valid()){state.page='welcome';render();}}
function roomMenu(){const r=state.room,host=r.hostId===r.meId,playing=r.hand?.status==='playing';openModal('牌桌菜单',`<div class="table-settings"><div class="data-row"><span>盲注</span><strong>${num(r.settings.smallBlind)} / ${num(r.settings.bigBlind)}</strong></div><div class="data-row"><span>带入范围</span><strong>${num(r.settings.minBuyIn)}–${num(r.settings.maxBuyIn)}</strong></div><div class="data-row"><span>行动时间</span><strong>${r.settings.actionSeconds} 秒</strong></div><div class="data-row"><span>带入审批</span><strong>${r.settings.approvalRequired?'房主审核':'自由带入'}</strong></div></div><div class="stack">${btn(state.animations?'动效：开':'动效：关','toggle-animations','outline')}${btn('玩法规则','rules','outline')}${btn('发牌与隐私','fairness','outline')}${r.hand?btn('核验当前牌局','verify','outline'):''}${host&&r.status!=='closed'?`${btn('调整房间设置','settings','outline',playing?'disabled':'')}${btn('转交房主','transfer-host','outline',playing?'disabled':'')}${btn('结束本场牌桌','close-room-confirm','danger',playing?'disabled':'')}`:''}${btn('回到大厅','lobby','ghost')}</div>${playing&&host?'<p class="note" style="margin-top:15px">本手结束后可修改设置、转交房主或结束牌桌。</p>':''}`,'room-menu');}
function rulesModal(){openModal('玩法规则',`<p class="note">BBPoker使用固定的本桌规则；房主在两手之间调整盲注、带入和小游戏设置。所有数值均为游戏积分。</p><h3 class="rule-title">德州扑克</h3><ol class="rule-list"><li>每人两张底牌，依次发出翻牌、转牌、河牌；用底牌与公共牌组成最强五张牌。</li><li>庄位顺时针轮转。两人局由庄家下小盲，翻牌前先行动、翻牌后后行动。</li><li>加注金额表示本轮累计下注总额。未达到完整加注的短码全下不会自动重新开放已行动玩家的加注权。</li><li>超时会自动过牌；需要跟注时自动弃牌。断线仍按同样计时，返回牌桌会恢复当前状态。</li><li>每手结束后由房主手动发下一手。在此期间可补码、暂离，或选择主动亮一张 / 两张底牌。</li><li>多人全下按实际投入分主池和边池；未被跟注的部分退回。平分后的零头从庄家左侧按座次分配。</li></ol><h3 class="rule-title">鱿鱼游戏 · 固定一轮</h3><ol class="rule-list"><li>至少 3 人参加，开轮时固定参与者，每人预留（人数 − 1）× 单位积分。</li><li>只有独自赢得主池才获得标记；平分主池和仅赢边池均不计。</li><li>最后一名未获标记者向本轮其他每人支付一份单位积分，未使用预留积分退回。</li><li>本轮中不能入座、离座或暂离；新入座申请等下一轮，两手间可以补码。</li><li>房主结束房间时，未完成一轮取消处罚，退回全部未用预留积分。</li></ol><h3 class="rule-title">蘑菇池 · 等小盲开花</h3><ol class="rule-list"><li>每名发牌玩家投入一份单位积分，小盲额外投入一份，独立于德州底池。</li><li>小盲独自赢得主池时，赢得全部蘑菇池；其他情况继续累积。</li><li>积分不足以支付费用并保留至少 1 分参与德州时，暂停开局并提示补码。</li><li>离座不会立即领回池内贡献；房间结束仍未派出的池，按实际贡献比例退回参与者。</li></ol><p class="note" style="margin-top:20px">带入只是游戏记分。平台不提供现金下注、充值、提现、陌生人匹配或自动对手。</p>`,'rules');}
function fairnessSourceLinks(sourceUrls) {
  const entries=Array.isArray(sourceUrls)?sourceUrls:sourceUrls&&typeof sourceUrls==='object'?Object.values(sourceUrls):[sourceUrls];
  const labels={'/api/source/poker.js':'查看洗牌、比牌与分池代码','/api/source/fairness.js':'查看发牌指纹校验代码'};
  return entries.map(entry=>{
    const value=typeof entry==='string'?{url:entry}:entry;
    if(!value||typeof value.url!=='string')return '';
    const href=value.url.trim(),relative=href.startsWith('/api/');
    if(/[\u0000-\u0020\\]/.test(href)||(!relative&&!/^https?:\/\//i.test(href)))return '';
    let url;try{url=new URL(href,'https://bbpoker.invalid');}catch{return '';}
    if(!['http:','https:'].includes(url.protocol)||url.username||url.password||(relative&&!url.pathname.startsWith('/api/')))return '';
    const label=typeof value.label==='string'&&value.label.trim()?value.label.trim():labels[url.pathname]||'查看源码（'+(url.pathname.split('/').filter(Boolean).at(-1)||url.hostname)+'）';
    return '<a class="note" href="'+esc(relative?apiUrl(href):href)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+' ↗</a>';
  }).join('');
}
async function fairnessModal(){openModal('发牌与隐私',`<p class="note">正在读取公开说明…</p>`,'fairness');try{const f=await api('/api/fairness');if(state.modal?.kind!=='fairness')return;const paragraphs=value=>(Array.isArray(value)?value:[value]).filter(Boolean).map(t=>`<p class="note">${esc(t)}</p>`).join('');openModal('发牌与隐私',`<p class="note brand-fairness-note">BBPoker 使用公开的随机洗牌实现与牌局承诺校验。它们不能代替独立审计；当前仍需信任服务器运行者。</p><h3 style="margin:16px 0 10px">密码学随机洗牌</h3>${paragraphs(f.summary)}<h3 class="rule-title">牌局承诺可以核验什么</h3><p class="note">每手开始锁定整副牌的承诺值。你可以核对当前已知牌与这一承诺是否一致；只有公共牌、你自己的底牌及主动公开的底牌会获得核验证明。</p><h3 class="rule-title">核验的边界</h3>${paragraphs(f.limits)||'<p class="note">承诺校验不能单独证明服务器最初没有挑选牌序，也不能防止玩家在平台外串通。源码与测试用于进一步审阅。</p>'}<div class="verification">版本：${esc(f.version||'公开版本')}<br>未公开底牌不会发送给其他玩家；牌谱和导出也保留相同隐私限制。</div>${f.sourceUrls?`<div class="stack" style="margin-top:16px">${fairnessSourceLinks(f.sourceUrls)}</div>`:''}${state.room?.hand?`<div class="modal-footer">${btn('核验当前牌局','verify','primary')}</div>`:''}`,'fairness');}catch(error){if(error.stale)return;toast(error.message,true);closeModal();}}
async function verifyHand(hand=state.room?.hand){if(!hand)return toast('开始第一手后即可核验');const proofs=hand.proofs||[],root=hand.commitment,receipt=receipts[hand.id],receiptMatches=receipt===root;openModal('核验已知牌',`<p class="note">正在本设备计算承诺证明…</p>`,'verify');const hash=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))).map(b=>b.toString(16).padStart(2,'0')).join('');try{if(!crypto.subtle)throw new Error('本地校验需要 HTTPS 或 localhost 的安全连接');const rows=await Promise.all(proofs.map(async proof=>{let value=await hash(`${hand.id}:${proof.position}:${proof.card}:${proof.salt}`);for(const sibling of proof.siblings||[])value=await hash(sibling.side==='left'?sibling.hash+value:value+sibling.hash);return {card:proof.card,valid:value===root};}));if(state.modal?.kind!=='verify')return;openModal('核验已知牌',`<p class="note">在你的设备上重新计算每张可见牌的 SHA-256 证明，并与本手发牌承诺对比。</p><div class="verification">${receipt?`<strong class="${receiptMatches?'positive':'negative'}">${receiptMatches?'✓ 与本机此前保存的承诺一致':'⚠ 与本机此前保存的承诺不一致'}</strong><br>`:'<span class="gold">本机没有这手的承诺回执，仅检查文件内部一致性。</span><br>'}${rows.length?`<strong>${rows.every(r=>r.valid)?'✓ 所有可见牌与文件承诺一致':'发现不一致，请保存牌局记录'}</strong><br>${rows.length} 张牌已检查`:'本手尚无可核验的可见牌'}<br><br>牌局 ID<br><span class="mono">${esc(hand.id)}</span><br><br>发牌承诺<br><span class="mono">${esc(root||'暂无')}</span></div><div class="row wrap" style="margin:17px 0">${rows.map(r=>`<div style="text-align:center">${card(r.card,'small-card')}<small class="${r.valid?'positive':'negative'}">${r.valid?'✓':'×'}</small></div>`).join('')}</div><p class="note">本机仅保存首次收到的承诺，不保存底牌或盐值；首次看到的时间可能晚于开局。校验不能独立证明服务器初始没有挑选牌序，也不能验证尚未公开的牌。</p>`,'verify');}catch(error){if(error.stale)return;toast(error.message,true);closeModal();}}
function eventText(event,players=state.room?.players||[]){if(typeof event==='string')return event;const name=players.find(p=>p.id===event.playerId)?.name||'',amount=event.type==='raise'?(event.to??event.amount):(event.amount??event.to);const labels={fold:'弃牌',check:'过牌',call:'跟注',raise:'加注至',allin:'全下',smallBlind:'小盲',bigBlind:'大盲',small_blind:'小盲',big_blind:'大盲',ante:'前注',refund:'退回未跟注积分',uncalled:'退回未跟注积分',win:'赢得',payout:'获得',deal:'发牌',flop:'发出翻牌',turn:'发出转牌',river:'发出河牌',showdown:'摊牌',street:'进入下一轮',start:'开始本手',complete:'本手结束',show:'主动亮牌'};return `${name?name+' · ':''}${labels[event.type]||event.type||'牌局更新'}${amount!==undefined?' '+num(amount):''}${event.board?.length?' · '+event.board.join(' '):''}`;}
async function historyModal(){if(!state.room)return;const code=state.room.code,guard=requests.capture();openModal('牌局记录',`<div class="empty"><span class="spinner"></span><p>读取牌局记录…</p></div>`,'history');try{const data=await api(`/api/rooms/${encodeURIComponent(code)}/history`);guard.check();if(state.modal?.kind!=='history')return;const list=data.hands||[];openModal('牌局记录',`<div class="row between" style="margin-bottom:15px"><span class="note" style="margin:0">${list.length} 手已完成 · 按你的身份展示</span>${btn('导出','export','outline small')}</div>${list.length?`<div class="history-list">${[...list].sort((a,b)=>Number(b.number)-Number(a.number)).map(h=>`<button class="history-item" data-action="replay" data-hand="${esc(h.id)}"><div><strong>第 ${num(h.number)} 手</strong><small class="muted" style="margin-left:7px">${esc(fmtDate(h.at))}</small><div class="board">${cards(h.board,'mini')}</div></div><div style="text-align:right"><strong class="${profitClass(h.profit)}">${h.profit==null?'查看':signed(h.profit)}</strong><small class="muted" style="display:block">回放 ↗</small></div></button>`).join('')}</div>`:'<div class="empty"><span class="empty-symbol">♧</span><div>暂无已完成牌局</div><p>完成一手后，可在这里逐步回看。</p></div>'}`,'history');}catch(error){if(error.stale)return;toast(error.message,true);closeModal();}}
async function replayModal(id,code=state.room?.code){const guard=requests.capture(),request=++state.replayRequest;if(!code)return;const origin=state.page==='hands'?'library':'room';openModal('牌局回放','<div class="empty"><span class="spinner"></span></div>','replay-loading');try{const response=await api(`/api/rooms/${encodeURIComponent(code)}/hands/${encodeURIComponent(id)}`),hand=response.hand||response;guard.check();if(state.modal?.kind!=='replay-loading'||request!==state.replayRequest)return;state.replay={hand,index:0,origin,favorite:hand.favorite??state.library.hands.find(h=>h.id===id)?.favorite??false};renderReplay();}catch(error){if(error.stale||request!==state.replayRequest)return;toast(error.message,true);closeModal();}}
function renderReplay(){
  const {hand,index}=state.replay,view=replaySnapshot(hand,index,state.user.id),stages=replayStreets(hand),log=hand.log||[];
  const body=`<div class="row between"><span class="note" style="margin:0">${esc(hand.roomName)} · ${esc(fmtDate(hand.at))}</span>${hand.players.some(p=>p.id===state.user.id)?btn(state.replay.favorite?'★ 已收藏':'☆ 收藏','favorite','ghost small',`data-hand="${esc(hand.id)}" data-favorite="${!state.replay.favorite}"`):''}</div><div class="replay-streets" aria-label="跳转至回合">${stages.map((step,i)=>btn(esc(step.label),'replay-street',index>=step.index&&(i===stages.length-1||index<stages[i+1].index)?'active':'',`data-index="${step.index}"`)).join('')}</div><div class="replay-table"><div class="pot-label">${view.complete?'已完成结算':'底池'}</div><strong class="pot-amount">${num(view.pot)}</strong><div class="board">${Array.from({length:5},(_,i)=>card(view.board[i],'',!view.board[i])).join('')}</div><div class="replay-caption">${view.lastEvent?esc(eventText(view.lastEvent,hand.players)):'开始 · 逐步查看这手牌'}</div></div><div class="replay-controls">${btn('‹','replay-prev','outline','aria-label="上一步" '+(index===0?'disabled':''))}${btn(state.replayTimer?'暂停':'播放','replay-play','primary')}${btn('›','replay-next','outline','aria-label="下一步" '+(index>=log.length?'disabled':''))}<select id="replay-speed" aria-label="回放速度">${[.5,1,2].map(speed=>`<option value="${speed}" ${state.replaySpeed===speed?'selected':''}>${speed}×</option>`).join('')}</select><span class="muted">${index} / ${log.length}</span></div><input type="range" aria-label="回放进度" id="replay-progress" min="0" max="${log.length}" value="${index}" class="replay-progress"><div class="replay-players">${view.players.map(p=>`<div class="replay-player ${p.folded?'folded':''}"><div class="row"><b>${esc(p.name)} ${p.id===state.user.id?'<span class="you-tag">我</span>':''}</b><strong>${num(p.stack)}</strong></div><div class="row replay-player-detail"><div class="row gap6">${cards(p.cards||[null,null],'mini')}</div><small>${view.complete?`德州 <span class="${profitClass(p.net)}">${signed(p.net)}</span><br>小游戏 ${signed(p.miniNet)}`:p.folded?'已弃牌':p.allIn?'全下':`本轮已下 ${num(p.bet)}`}</small></div>${view.complete&&p.endingStack!=null?`<small class="ending-stack">结算后总积分 ${num(p.endingStack)}</small>`:''}</div>`).join('')}</div><details class="replay-log-details"><summary>逐步记录</summary><div class="replay-log">${log.map((e,i)=>`<button type="button" data-action="replay-street" data-index="${i+1}" class="${i===index-1?'current':''} ${i>=index?'future':''}">${i+1}. ${esc(eventText(e,hand.players))}</button>`).join('')}</div></details><p class="privacy-footnote">他人已公开底牌在结算步展示，未公开底牌始终隐藏。过程中积分只计德州，小游戏结算单列。</p><div class="row between">${btn(state.replay.origin==='library'?'返回牌谱':'本桌牌谱',state.replay.origin==='library'?'close-modal':'history','ghost small')}${btn('核验这手牌','verify-history','outline small')}</div>`;
  const timer=state.replayTimer;state.replayTimer=null;const active=document.activeElement?.id,scroll=dialog.scrollTop;openModal(`第 ${num(hand.number)} 手牌回放`,body,'replay');state.replayTimer=timer;dialog.scrollTop=scroll;if(active&&dialog.querySelector('#'+active))dialog.querySelector('#'+active).focus({preventScroll:true});
}
function stopReplay(){clearInterval(state.replayTimer);state.replayTimer=null;}
function playReplay(){stopReplay();if(state.replay.index>=state.replay.hand.log.length)state.replay.index=0;state.replayTimer=setInterval(()=>{if(state.modal?.kind!=='replay'){stopReplay();return;}state.replay.index++;if(state.replay.index>=state.replay.hand.log.length)stopReplay();renderReplay();},1000/state.replaySpeed);renderReplay();}
async function replayLastHand(){if(!state.room)return;const guard=requests.capture(),code=state.room.code;try{const data=await api(`/api/rooms/${encodeURIComponent(code)}/history`);guard.check();const latest=[...(data.hands||[])].sort((a,b)=>Number(b.number)-Number(a.number))[0];if(latest)await replayModal(latest.id,code);else toast('完成第一手后即可回放');}catch(error){if(!error.stale)toast(error.message,true);}}

function exportModal(){state.exportRoom=state.room?.code||state.library.room||'';openModal('导出牌谱',`<form id="export-form"><p class="note">只包含自己的底牌和已公开牌。</p><label class="field">导出格式<select name="format"><option value="json">JSON · 完整结构，便于备份与核验</option><option value="txt">TXT · 易读逐手牌谱</option><option value="csv">CSV · 用表格分析</option><option value="phh">PHH · 通用牌谱，便于其他工具读取</option></select></label><details class="help-details"><summary>筛选日期</summary><div class="field-grid"><label class="field">开始日期<input name="from" type="date"></label><label class="field">结束日期<input name="to" type="date"></label></div></details><div class="modal-footer">${btn('取消','close-modal','ghost')}<button type="submit" class="primary">下载记录</button></div></form>`,'export');}
async function handleAction(button){const action=button.dataset.action;if(button.disabled)return;switch(action){case'lobby':navigate('');break;case'career':navigate('/career');break;case'hands':navigate('/hands');break;case'library-all':state.library.favorites=false;await loadLibrary(true);break;case'library-favorites':state.library.favorites=true;await loadLibrary(true);break;case'library-retry':await loadLibrary(true);break;case'library-more':await loadLibrary();break;case'favorite':await favoriteHand(button.dataset.hand,button.dataset.favorite==='true',button);break;case'toggle-chat':state.chatOpen=!state.chatOpen;if(state.chatOpen)state.chatUnread=0;render();break;case'mute-chat':state.chatMuted=!state.chatMuted;state.chatUnread=0;render();break;case'mute-reactions':state.reactionsMuted=!state.reactionsMuted;state.reactions={};render();break;case'toggle-animations':state.animations=!state.animations;state.motion=null;document.documentElement.classList.toggle('no-motion',!state.animations);roomMenu();break;case'send-emote':await sendChat('emote',button.dataset.emote);break;case'last-hand':await replayLastHand();break;case'retry':boot();break;case'close-modal':closeModal();break;case'create':createModal();break;case'open-room':navigate(`/room/${encodeURIComponent(button.dataset.code)}`);break;case'profile':profileModal();break;case'restore':restoreModal();break;case'auth-login':case'auth-register':requests.invalidate();state.authMode=action==='auth-register'?'register':'login';render();break;case'recover':recoverModal();break;case'bind-account':bindAccountModal();break;case'change-password':changePasswordModal();break;case'copy-token':if(!state.user?.username)await copy(state.token,'旧恢复码已复制，请私下保存');break;case'copy-recovery':if(state.pendingRecovery)await copy(state.pendingRecovery.code,'找回码已复制，请私下保存');break;case'save-recovery':if(state.pendingRecovery){const r=state.pendingRecovery,result=await saveExport({name:'BBPoker-账号找回码.txt',content:`网站：https://bbpoker.fun
账号：${r.username}
找回码：${r.code}
请私下保存。用于忘记密码时设置新密码；修改密码后旧码失效。
`,mime:'text/plain;charset=utf-8'});if(!result.canceled)toast('找回资料已交给系统保存');}break;case'recovery-done':state.pendingRecovery=null;await route();break;case'logout-confirm':if(state.user?.username){openModal('退出登录',`<p class="note">牌谱和积分记录仍会保留，下次用账号密码登录。</p><div class="modal-footer">${btn('取消','close-modal','ghost')}${btn('退出当前设备','logout','danger')}</div>`);}else openModal('退出前，留好旧恢复码',`<p class="note">你尚未设置账号。请保存旧恢复码，下次用它找回当前昵称和记录。</p><div class="recovery">${esc(state.token)}</div><div class="modal-footer">${btn('复制旧恢复码','copy-token','outline')}${btn('已保存，退出','logout','danger')}</div>`);break;case'logout':await logout();break;case'choose-seat':toast('点击牌桌周围带 ＋ 的空座位');document.querySelector('.table-stage')?.scrollIntoView({behavior:'smooth',block:'center'});break;case'sit':buyinModal(Number(button.dataset.seat));break;case'buyin':buyinModal();break;case'invite':inviteModal();break;case'copy-invite':await copy($('#invite-link').value,'邀请已复制，发给你的朋友吧');break;case'share-invite':await shareInvitation({title:`BBPoker · ${state.room.name}`,text:'BBPoker给你留了个位置，来和朋友打一场积分局。',url:$('#invite-link').value});break;case'room-menu':roomMenu();break;case'rules':rulesModal();break;case'fairness':fairnessModal();break;case'verify':verifyHand();break;case'verify-history':verifyHand(state.replay.hand);break;case'settings':openModal('调整牌桌设置',`<form id="settings-form"><p class="note">仅两手之间可修改；小游戏进行中可能限制相关设置。</p>${settingFields(state.room.settings)}<div class="modal-footer">${btn('取消','close-modal','ghost')}<button class="primary" type="submit">保存设置</button></div></form>`,'settings');break;case'approve':case'reject':await command(action,{requestId:button.dataset.request});break;case'fold':case'check':case'call':await command(action);break;case'raise':await command('raise',{amount:state.raise});break;case'allin':await command('allin');break;case'raise-preset':{const a=state.room.actions,me=state.room.players.find(p=>p.id===state.room.meId);const pot=Number(state.room.hand.pot)||0,call=Number(a.callAmount)||0,total=Number(me?.bet||0)+call;const value=button.dataset.preset==='min'?a.minRaiseTo:button.dataset.preset==='all'?a.maxRaiseTo:total+Math.floor((pot+call)*(button.dataset.preset==='half'?.5:1));setRaise(value);break;}case'start':await command('start');break;case'stand':openModal('离开座位',`<p class="note">你会留在房间观战。当前积分将按记录结算，之后可重新申请入座。鱿鱼轮未结束时不能离座。</p><div class="modal-footer">${btn('继续坐着','close-modal','ghost')}${btn('确认离座','stand-confirm','outline')}</div>`);break;case'stand-confirm':if(await command('stand'))closeModal();break;case'sitout':{const me=state.room.players.find(p=>p.id===state.room.meId);await command('sitout',{value:!me?.sittingOut});break;}case'show':{state.showHandId=state.room.hand?.id;const me=state.room.players.find(p=>p.id===state.room.meId);openModal('主动亮牌',`<p class="note">主动亮牌后，房间成员和你的历史牌谱中都会保留公开状态，无法再隐藏。</p><div class="row" style="justify-content:center;gap:22px;margin:24px 0">${(me?.cards||[]).map((v,i)=>`<div class="stack" style="justify-items:center;gap:12px">${card(v)}${btn(state.revealed.has(i)?'已公开':`亮第 ${i+1} 张`,'show-one','outline small',`data-index="${i}" ${state.revealed.has(i)?'disabled':''}`)}</div>`).join('')}</div><div class="modal-footer">${btn('两张都亮','show-both','primary')}</div>`,'show');break;}case'show-one':{const index=Number(button.dataset.index);if(await command('show',{indices:[index],handId:state.showHandId})){state.revealed.add(index);toast('已向牌友公开这张牌');closeModal();}break;}case'show-both':if(await command('show',{indices:[0,1],handId:state.showHandId})){state.revealed.add(0);state.revealed.add(1);toast('两张底牌已公开');closeModal();}break;case'transfer-host':openModal('转交房主',`<p class="note">接任的朋友将获得审批、设置、开局及结束房间权限。</p><div class="stack">${state.room.players.filter(p=>p.id!==state.room.meId).map(p=>btn(`${esc(p.name)} ↗`,'transfer-confirm','outline',`data-player="${esc(p.id)}"`)).join('')||'<p class="note">还没有可以接任的朋友。</p>'}</div>`);break;case'transfer-confirm':if(await command('transferHost',{playerId:button.dataset.player}))closeModal();break;case'close-room-confirm':openModal('结束牌桌',`<p class="note">结束后不能再继续发牌。鱿鱼未使用预留积分全部退回，蘑菇池按实际贡献比例退回；历史与积分记录继续保留。</p><div class="modal-footer">${btn('继续同桌','close-modal','ghost')}${btn('结算并结束','close-room','danger')}</div>`);break;case'close-room':if(await command('close')){closeModal();toast('牌桌已结束，记录已经保留');}break;case'history':historyModal();break;case'replay':replayModal(button.dataset.hand,button.dataset.room||state.room?.code);break;case'replay-prev':stopReplay();state.replay.index=Math.max(0,state.replay.index-1);renderReplay();break;case'replay-next':stopReplay();state.replay.index=Math.min(state.replay.hand.log.length,state.replay.index+1);renderReplay();break;case'replay-end':case'replay-street':stopReplay();state.replay.index=action==='replay-end'?state.replay.hand.log.length:Math.max(0,Math.min(state.replay.hand.log.length,Number(button.dataset.index)||0));renderReplay();break;case'replay-play':if(state.replayTimer){stopReplay();renderReplay();}else playReplay();break;case'export':exportModal();break;case'install':if(state.install){await state.install.prompt();await state.install.userChoice;state.install=null;render();}break;}}
function setRaise(value){const a=state.room?.actions;if(!a?.canRaise)return;state.raise=Math.max(a.minRaiseTo,Math.min(a.maxRaiseTo,Math.round(Number(value)||a.minRaiseTo)));if($('#raise-range'))$('#raise-range').value=state.raise;if($('#raise-input'))$('#raise-input').value=state.raise;if($('#raise-button'))$('#raise-button').textContent=`加至 ${num(state.raise)}`;}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button)handleAction(button).catch(error=>toast(error.message,true));});
document.addEventListener('compositionstart',event=>{if(app.contains(event.target))state.composing=true;});
document.addEventListener('compositionend',event=>{state.composing=false;if(event.target.id==='chat-input')state.chatDraft=event.target.value;if(state.renderDeferred)render();});
document.addEventListener('input',event=>{if(event.target.id==='chat-input')state.chatDraft=event.target.value;updateSettingConstraints(event.target.form);if(event.target.id==='raise-range')setRaise(event.target.value);if(event.target.id==='raise-input'){const a=state.room?.actions,n=Number(event.target.value);if(a?.canRaise&&Number.isSafeInteger(n)&&n>=a.minRaiseTo&&n<=a.maxRaiseTo){state.raise=n;$('#raise-range').value=n;$('#raise-button').textContent=`加至 ${num(n)}`;}}if(event.target.id==='replay-progress'){stopReplay();state.replay.index=Number(event.target.value);renderReplay();}});
document.addEventListener('change',event=>{const input=event.target;if(input.id==='library-room'){state.library.room=input.value;loadLibrary(true);}if(input.id==='replay-speed'){state.replaySpeed=Number(input.value)||1;if(state.replayTimer)playReplay();}if(input.id==='raise-input')setRaise(input.value);if(input.dataset.miniToggle){const config=document.getElementById(input.dataset.miniToggle);if(config){config.hidden=!input.checked;for(const field of config.querySelectorAll('input'))field.disabled=!input.checked;}}const form=input.form;if(form?.matches('#create-form,#settings-form')){const settings=readSettings(form),summary=form.querySelector('[data-settings-overview]');if(summary)summary.textContent=`${settings.maxPlayers} 人桌 · 带入 ${num(settings.minBuyIn)}–${num(settings.maxBuyIn)} · ${settings.actionSeconds} 秒 · ${settings.approvalRequired?'房主审核':'自由带入'}`;}});
document.addEventListener('invalid',event=>{const details=event.target.closest('details');if(details)details.open=true;},true);
document.addEventListener('toggle',event=>{if(event.target.id==='table-activity'&&event.target.isConnected)state.activityOpen=event.target.open;},true);
document.addEventListener('submit',async event=>{const form=event.target;if(!form.id)return;event.preventDefault();if(form.id==='chat-form'&&state.composing)return;const submit=form.querySelector('[type=submit]');if(submit?.disabled)return;if(submit)submit.disabled=true;const fd=new FormData(form),guard=requests.capture();try{switch(form.id){case'chat-form':await sendChat('text',String(fd.get('text')||''));break;case'login-form':await submitAccount('login',fd);break;case'register-form':await submitAccount('register',fd);break;case'bind-account-form':await submitAccount('bind',fd);break;case'password-form':await submitAccount('password',fd);break;case'recover-form':await submitAccount('recover',fd);break;case'restore-form':{const data=await api('/api/session/restore',{token:String(fd.get('token')).trim()},{anonymous:true});await adoptIdentity(data);closeModal();await route();toast('身份已恢复');break;}case'join-form':joinInvite(String(fd.get('invite')));break;case'create-form':{const result=await api('/api/rooms',{name:String(fd.get('name')).trim(),settings:readSettings(form),createKey:String(fd.get('createKey')||'')});closeModal();const room=result.room||result;navigate(`/room/${encodeURIComponent(room.code)}/${encodeURIComponent(room.invite)}`);break;}case'buyin-form':{const amount=Number(fd.get('amount')),isSit=form.dataset.seat!=='';if(await command(isSit?'sit':'buyin',{amount,...(isSit?{seat:Number(form.dataset.seat)}:{})}))closeModal();break;}case'settings-form':if(await command('settings',{settings:readSettings(form)}))closeModal();break;case'export-form':{const format=String(fd.get('format')),query=new URLSearchParams({format});if(state.exportRoom)query.set('room',state.exportRoom);if(fd.get('from'))query.set('from',new Date(String(fd.get('from'))+'T00:00:00').toISOString());if(fd.get('to'))query.set('to',new Date(String(fd.get('to'))+'T23:59:59.999').toISOString());const exportToken=state.token,response=await fetch(apiUrl(`/api/export?${query}`),{headers:{Authorization:`Bearer ${exportToken}`},cache:'no-store'});guard.check();if(response.status===401){await expireIdentity(exportToken);guard.check();}if(!response.ok){const e=await response.json().catch(()=>({}));throw new Error(e.error||'导出暂时失败');}let content=await response.text();guard.check();if(format==='csv'&&!content.startsWith('\uFEFF'))content='\uFEFF'+content;const result=await saveExport({name:`BBPoker-${state.exportRoom||'我的生涯'}-${new Date().toISOString().slice(0,10)}.${format==='phh'?'phhs':format}`,content,mime:response.headers.get('Content-Type')||'text/plain'});if(!result.canceled&&guard.valid()){toast('记录已交给系统保存');closeModal();}break;}}}catch(error){if(!error.stale)toast(error.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}});
function resetPrivateView(){requests.invalidate();stopStream();closeModal();state.room=null;state.stats=null;state.rooms=[];state.replay=null;state.showHandId=null;state.revealed=new Set();state.busy=false;state.activityOpen=false;state.pendingRecovery=null;state.chatDraft='';state.chatBusy=false;state.chatPending=null;state.chatOpen=false;state.chatUnread=0;state.reactions={};state.motion=null;state.composing=false;state.library={hands:[],nextCursor:null,favorites:false,room:'',loading:false,error:'',request:state.library.request+1};}
async function expireIdentity(token){
  if(!token||state.token!==token)return;
  resetPrivateView();const guard=requests.capture();state.token='';state.user=null;state.authMode='login';state.page='loading';render();
  await clearIdentity(token).catch(()=>{});if(!guard.valid())return;
  state.page='welcome';render();toast('登录已失效，请重新登录；牌谱和积分记录仍会保留',true);
}
async function adoptIdentity(data){
  resetPrivateView();
  state.token=data.token;state.user=data.user;state.identityEphemeral=false;state.page='loading';render();const guard=requests.capture();
  try{await writeIdentity(data.token);}catch{guard.check();state.identityEphemeral=true;toast(data.user.username?'本设备未能记住登录，下次请用账号密码登录':'本设备暂时无法保存身份，请保存旧恢复码',true);}
  guard.check();
}
function resumeTable(){
  if(state.page==='room'&&state.room&&navigator.onLine&&document.visibilityState!=='hidden'){abortPendingTableRequests();connectStream(state.room.code);}
}
window.addEventListener('hashchange',route);
window.addEventListener('online',resumeTable);
window.addEventListener('offline',()=>{stopStream();state.connection='网络已断开';updateConnection();});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();state.install=event;if(state.page==='lobby')render();});
document.addEventListener('visibilitychange',()=>{
  if(document.visibilityState==='visible')resumeTable();
  else if(state.page==='room'){stopStream();state.connection='返回后同步牌桌';updateConnection();}
});
window.addEventListener('pageshow',event=>{if(event.persisted)resumeTable();});
bindNativeLifecycle({resume:resumeTable,back:()=>{if(dialog.open)closeModal();else if(state.page!=='lobby'&&state.page!=='welcome')navigate('');}});
async function boot(){
  requests.invalidate();const guard=requests.capture();state.page='loading';state.error='';render();
  try{
    const config=clientConfig();
    if(!config.native&&'serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
    const savedToken=state.token||await readIdentity();guard.check();state.token=savedToken;
    if(!state.token){state.page='welcome';render();return;}
    await loadMe();guard.check();await route();
  }catch(error){
    if(error.stale||!guard.valid())return;
    if(error.status===401){await clearIdentity(state.token).catch(()=>{});if(!guard.valid())return;state.token='';state.user=null;state.page='welcome';toast('登录已失效，请重新登录',true);}
    else{state.error=error.message;state.page='error';}
    render();
  }
}
boot();
